sysauto_script.script:
(function autoCompleteLearningRequests() {

    var TABLE_NAME =
        'x_1549902_asean_0_learning_application';

    var STATE_FIELD = 'state';
    var COURSE_END_DATE_FIELD = 'course_end_date';
    var COMMENTS_FIELD = 'comments';

    var APPROVED_STATE = 'approved';
    var COMPLETED_STATE = 'completed';

    /*
     * Calculate the date exactly 30 days before today.
     *
     * Example:
     * Today       : 2026-07-20
     * Cutoff date : 2026-06-20
     */
    var cutoffGDT = new GlideDateTime();
    cutoffGDT.addDaysLocalTime(-30);

    /*
     * getLocalDate() returns a GlideDate.
     * getValue() returns yyyy-MM-dd, suitable for a Date field query.
     */
    var cutoffDate = cutoffGDT.getLocalDate().getValue();

    gs.info(
        '[ASEAN Learning Auto Complete] Today: ' +
        new GlideDate().getValue() +
        ', cutoff date: ' +
        cutoffDate
    );

    var learningGR = new GlideRecord(TABLE_NAME);

    /*
     * Fetch approved records where course end date is
     * exactly 30 days ago or more than 30 days ago.
     */
    learningGR.addQuery(
        STATE_FIELD,
        APPROVED_STATE
    );

    learningGR.addNotNullQuery(
        COURSE_END_DATE_FIELD
    );

    learningGR.addQuery(
        COURSE_END_DATE_FIELD,
        '<=',
        cutoffDate
    );

    learningGR.query();

    gs.info(
        '[ASEAN Learning Auto Complete] Matching record count: ' +
        learningGR.getRowCount()
    );

    var completedCount = 0;

    while (learningGR.next()) {

        var requestNumber =
            learningGR.getDisplayValue('number');

        var courseEndDate =
            learningGR.getDisplayValue(
                COURSE_END_DATE_FIELD
            );

        /*
         * Reconfirm that the record is still approved.
         */
        if (
            learningGR.getValue(STATE_FIELD) !==
            APPROVED_STATE
        ) {
            continue;
        }

        learningGR.setValue(
            STATE_FIELD,
            COMPLETED_STATE
        );

        /*
         * Add the message to Comments.
         */
        learningGR.setValue(
            COMMENTS_FIELD,
            'System Update: This learning request has been ' +
            'automatically marked as Completed because 30 days ' +
            'have elapsed since the course end date (' +
            courseEndDate +
            ').'
        );

        var updatedSysId = learningGR.update();

        if (updatedSysId) {

            completedCount++;

            gs.info(
                '[ASEAN Learning Auto Complete] Request ' +
                requestNumber +
                ' completed successfully. Course end date: ' +
                courseEndDate
            );

        } else {

            gs.error(
                '[ASEAN Learning Auto Complete] Failed to update request ' +
                requestNumber
            );
        }
    }

    gs.info(
        '[ASEAN Learning Auto Complete] Total records completed: ' +
        completedCount
    );

})();
